function save_brand_asset(string $field, string $current): string { if (empty($_FILES[$field]) || ($_FILES[$field]['error'] ?? UPLOAD_ERR_NO_FILE) === UPLOAD_ERR_NO_FILE) return $current; $file=$_FILES[$field]; if (($file['error'] ?? 1)!==UPLOAD_ERR_OK || (int)$file['size']>5*1024*1024) throw new RuntimeException('Branding images must be smaller than 5MB.'); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']); $allowed=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp','image/gif'=>'gif','image/x-icon'=>'ico']; if(!isset($allowed[$mime])) throw new RuntimeException('Unsupported branding image type.'); $dir=APP_ROOT.'/uploads/branding'; if(!is_dir($dir)&&!mkdir($dir,0750,true)) throw new RuntimeException('Could not create upload directory.'); $name=$field.'-'.bin2hex(random_bytes(12)).'.'.$allowed[$mime]; if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name)) throw new RuntimeException('Could not save image.'); return '/uploads/branding/'.$name; }
